def best(N):
    els=list(range(1,N+1)); b=0
    def rec(i,chosen):
        nonlocal b
        if len(chosen)+(N-i)<=b: return
        if i==N:
            b=max(b,len(chosen)); return
        x=els[i]
        if all(x%c!=0 for c in chosen): rec(i+1,chosen+[x])
        rec(i+1,chosen)
    rec(0,[]); return b
for n in range(1,9): assert best(2*n)==n

