from itertools import permutations
import random
def lis(x):
    L=[1]*len(x)
    for i in range(len(x)):
        for j in range(i):
            if x[j]<x[i]: L[i]=max(L[i],L[j]+1)
    return max(L)
mono=lambda x: max(lis(x),lis([-t for t in x]))
assert all(mono(p)>=3 for p in permutations(range(5)))
assert any(mono(p)<3 for p in permutations(range(4)))
random.seed(3)
for _ in range(20000):
    p=random.sample(range(100),10); assert mono(p)>=4
assert mono([7,8,9,4,5,6,1,2,3])==3

